import { useMemo } from "react";
import { useParams } from "react-router-dom";
import templates from "../templates";
import "../document.css";

/* =========================
   BASE64 IMAGES (PASTE HERE)
   ========================= */
const HEADER_IMG = "data:image/png;base64,";
const FOOTER_IMG = "data:image/png;base64,";
const WATERMARK_IMG = "data:image/png;base64,";

/* normalize helper */
function normalizeKey(s = "") {
  return String(s).replace(/[^a-z0-9]/gi, "").toLowerCase();
}

/* template finder */
function findTemplateKey(templatesObj, rawDocType) {
  if (!rawDocType) return null;
  const keys = Object.keys(templatesObj || {});
  const target = normalizeKey(rawDocType);

  let found = keys.find((k) => normalizeKey(k) === target);
  if (found) return found;

  found = keys.find(
    (k) =>
      normalizeKey(k).includes(target) ||
      target.includes(normalizeKey(k))
  );
  return found || null;
}

/* detect html */
function isHtmlString(s = "") {
  return /<\/?[a-z][\s\S]*>/i.test(s);
}

/* =========================
   WORD SAFE HTML
   ========================= */
function buildWordHtml(content) {
  return `
<html xmlns:o="urn:schemas-microsoft-com:office:office"
      xmlns:w="urn:schemas-microsoft-com:office:word">
<head>
<meta charset="utf-8"/>
<style>
@page { size:A4; margin:25mm; }
body { font-family: Arial; font-size: 12pt; }

.header img { width:100%; }
.footer img { width:100%; }

.watermark {
  position: fixed;
  top: 35%;
  left: 25%;
  opacity: 0.08;
}
</style>
</head>

<body>

<div style="mso-element:header" class="header">
  <img src="${HEADER_IMG}" />
</div>

<div class="watermark">
  <img src="${WATERMARK_IMG}" width="300"/>
</div>

${content}

<div style="mso-element:footer" class="footer">
  <img src="${FOOTER_IMG}" />
</div>

</body>
</html>`;
}

export default function GenerateDocument() {
  const { docType } = useParams();
  const rawDocType = decodeURIComponent(docType || "");

  const templateKey = useMemo(
    () => findTemplateKey(templates, rawDocType),
    [rawDocType]
  );

  const templateFn = templateKey ? templates[templateKey] : null;

  if (!templateFn) {
    return (
      <div style={{ padding: 40 }}>
        <h1>Generate Page</h1>
        <p style={{ color: "red" }}>
          Template not found for this document type.
        </p>
        <button disabled>Download PDF</button>{" "}
        <button disabled>Download Word</button>
      </div>
    );
  }

  const rawContent = templateFn({
    companyName: "Demo Company",
    bidNumber: "BID-XXXX-001",
    date: new Date().toLocaleDateString(),
    authority: "Authorized Signatory",
  });

  const content =
    typeof rawContent === "string" ? rawContent : String(rawContent);

  const finalHtml = isHtmlString(content)
    ? content
    : `<pre>${content}</pre>`;

  /* WORD DOWNLOAD */
  const downloadWord = () => {
    const wordHtml = buildWordHtml(finalHtml);
    const blob = new Blob([wordHtml], {
      type: "application/msword;charset=utf-8",
    });

    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `${templateKey}.doc`;
    a.click();
    URL.revokeObjectURL(url);
  };

  /* PDF PRINT */
  const downloadPdf = () => {
    const w = window.open("", "_blank");
    if (!w) return alert("Popup blocked");

    w.document.write(`
      <html>
        <head>
          <style>
            @page { size:A4; margin:25mm; }
            body { font-family: Arial; }
          </style>
        </head>
        <body>${finalHtml}</body>
      </html>
    `);

    w.document.close();
    w.focus();
    setTimeout(() => w.print(), 300);
  };

  return (
    <div style={{ padding: 40 }}>
      <h1>Generate Page</h1>

      {/* PREVIEW */}
      <div className="doc-wrapper">
        <div className="doc-header" />
        <div className="doc-watermark" />
        <div
          className="doc-content"
          dangerouslySetInnerHTML={{ __html: finalHtml }}
        />
        <div className="doc-footer" />
      </div>

      <div style={{ marginTop: 20 }}>
        <button onClick={downloadPdf}>Download PDF</button>{" "}
        <button onClick={downloadWord}>Download Word</button>
      </div>
    </div>
  );
}
